package com.wayrapass.security;
import com.wayrapass.exception.UnauthorizedException; import com.wayrapass.model.User; import com.wayrapass.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class CurrentUser { private final UserRepository users; public User require(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!(a.getPrincipal() instanceof UserPrincipal p))throw new UnauthorizedException("Se requiere autenticación.");return users.findById(p.getId()).orElseThrow(()->new UnauthorizedException("El usuario autenticado ya no existe."));} public Long id(){return require().getId();} }
